import{_ as t,o,c as e,ag as a}from"./chunks/framework.DaAXJYxM.js";const q=JSON.parse('{"title":"第109章 四版行程","description":"","frontmatter":{},"headers":[],"relativePath":"第109章_四版行程.md","filePath":"第109章_四版行程.md"}'),_={name:"第109章_四版行程.md"};function r(n,p,s,u,c,i){return o(),e("div",null,[...p[0]||(p[0]=[a('<h1 id="第109章-四版行程" tabindex="-1">第109章 四版行程 <a class="header-anchor" href="#第109章-四版行程" aria-label="Permalink to &quot;第109章 四版行程&quot;">​</a></h1><p>那年冬天我整理到第三年。</p><p>也就是我们之间那八周。</p><p>我把那个压缩包点开的时候，我以为我读的是同一件事。</p><p>我读到最后发现，那里面有两件事。</p><p>我先讲我看见的。</p><p>那一夜是十一月的第九天。</p><p>那天她上线很早。</p><p>她那边下午两点，我这边夜里七点。</p><p>她发的是：</p><p>她说，我今天算了三天，我算出来一个东西。</p><p>我说，什么。</p><p>她说，我明年二月有九天假。</p><p>她说，九天。</p><p>我说，那你要干什么。</p><p>她说，我要算一遍我怎么从这边到你那个城市。</p><p>我说，你算这个干什么。</p><p>她说，我要是算出来我这边能走，我就走。</p><p>她说，我要是算出来我不能走，我明年就安心画图。</p><p>她说，我今天把这两条都算完了。</p><p>她说，我先说我算的第一版。</p><p>她说，第一版：我二月六号走，八号到你那儿，十号回，一共九天，机票单程三千二。</p><p>她说，这个太贵，我下个月白干。</p><p>她说，第二版：我改二月十九号走，二十三号回。</p><p>她说，我算出来那几天有票，两千一。</p><p>她说，但二十三号我二十八号要交图。</p><p>她说，我要是二十三号回来我二十四二十五两天画，画不完。</p><p>她说，那不行。</p><p>她说，第三版：我二月十九号走，二十七号回。</p><p>她说，我把图提前画完，我十二月底开始每天多做一张。</p><p>她说，我这样我能见你八天。</p><p>她说，八天里我住哪儿我算好了，你们那个站旁边有一个六十八一晚的，我住了两次，我知道那家。</p><p>她说，我这一版全部加起来四千七。</p><p>我说，那你为什么还有一版。</p><p>她隔了一会儿。</p><p>她说，第四版是我不去。</p><p>她说，第四版：我把这四千七留下来，我三月交那个展的费用。</p><p>她说，我今天算到第四版，我停在那儿很久。</p><p>我说，那你最后定了哪个。</p><p>她说，第三版。</p><p>她说，我今天早上定了第三版。</p><p>她说，我买票以前我要跟你说一声。</p><p>我说，你说。</p><p>她说，我要是二月份来了，你不要到站里接我。</p><p>我说，为什么。</p><p>她说，因为你到站里我就会开始看你的脸，看你高不高兴。</p><p>她说，我要是看出来你不高兴，我这一天就废了。</p><p>她说，我在车上那六个钟头我要用来想我要怎么跟你讲话。</p><p>她说，你到站里我就没时间想了。</p><p>我说，那我在哪儿。</p><p>她说，你在你那个住的地方等我。</p><p>她说，我打表过去。</p><p>她说，我到了我敲门。</p><p>她说，你一开门我就知道我今天这个决定对不对。</p><p>她说，你不用讲话。</p><p>她说，你开门就行。</p><p>那天夜里我们讲了四十七分钟。</p><p>她讲的全是几站。</p><p>她从那个站到她住的那个酒店要坐几路，几站，几块钱。</p><p>她从酒店到我那儿要换一次车，她查过那个换车站有没有座位。</p><p>她讲了那个包要带哪几样。</p><p>她说她要把那本画册带上，她说她那边有一页我要看。</p><p>她说她要带一支笔，她要给我写一点东西。</p><p>她说她要带那个杯盖的原件——那天她落在我那儿的那个杯盖的另一半，她一直留着。</p><p>她说她两半要凑齐一次。</p><p>那天晚上我下线是十一点四十三。</p><p>我第二天早上七点起来，我看了一眼那个空文件夹。</p><p>我没有进去。</p><p>那年十一月第九天，她把这三十七个小时的行程排了四版。</p><p>她算到几站，算到那个换车站有没有座位。</p><p>她算的时候是她的夜里两点。</p><p>她给我发消息是她的下午两点。</p><p>她那边下午两点的时候，她昨天夜里没睡。</p><p>这些是我今年冬天读到的。</p><p>今年冬天我读到的是另一部分。</p><p>我把那个十一月的记录往下翻。</p><p>我翻到同一周的我的记录。</p><p>我在那一周里，跟陈树在吃一个饭。</p><p>陈树那天说，你俩到底图什么。</p><p>我说，我不图什么。</p><p>陈树说，那你为什么还不散。</p><p>我说，我像在赎罪。</p><p>我说这句话是十一月十三号晚上八点四十一。</p><p>而她那边是下午三点四十一。</p><p>她那天下午三点四十一在干什么，我今年才查出来。</p><p>她在银行，她在算那笔四千七。</p><p>她在银行里排了四十分钟。</p><p>她排的时候给我发过一条。</p><p>那条发在我这边晚上七点五十。</p><p>我那时候在饭馆里。</p><p>她那条只有七个字：那个酒店有单人房。</p><p>我看到了。</p><p>我看见的是&quot;单人房&quot;这四个字。</p><p>我没有回。</p><p>我当时把手机扣在桌上，我继续跟陈树讲我那句&quot;我像在赎罪&quot;。</p><p>那天我讲了二十分钟。</p><p>我讲的是：我不需要她给我什么，我把这个还完我就自由了。</p><p>今年冬天我坐在电脑前，把这两件事摆在一起看。</p><p>我把十一月的第九天到第十三天那五天，全部读了一遍。</p><p>我读完以后我在那把椅子上坐了很久。</p><p>那五天里：</p><p>她在算怎么从一万里以外到我面前。</p><p>我在算怎么把这段关系变成一笔还得清的债。</p><p>我们两个每天都在讲话。</p><p>我们两个一天也没讲过同一件事。</p><p>我那天下午给陈树打了一个电话。</p><p>我说，我那年十一月在你那儿讲的那句&quot;我在赎罪&quot;，你还记不记得。</p><p>陈树隔了很久。</p><p>他说，记得。</p><p>我说，我当时讲完你什么反应。</p><p>他说，我没讲话。</p><p>我说，为什么。</p><p>他说，因为那天你要的是我点头。</p><p>他说，我要是点头，你明天就去跟她讲你还完了。</p><p>他说，我怕你那时候去讲这句话。</p><p>他说，我不知道她那天在银行排队。</p><p>他说，你要是那天讲了&quot;我还完了，我自由了&quot;，她那个四千七就在银行那个队里废了。</p><p>我那天下午三点在办公室里坐着。</p><p>我说，你为什么现在才讲。</p><p>陈树说，你现在问我，我讲。</p><p>我说，我那年没问你。</p><p>他说，对。</p><p>他说，你那年没问过我一句&quot;我今天讲的这个对不对&quot;。</p><p>他说，你那天晚上跟我讲了二十分钟，你要的是我听着。</p><p>他说，我给你听着了。</p><p>他说，你今天问我，我告诉你。</p><p>他说，你那年那句话，讲早了五天。</p><p>我那天把那个十一月的压缩包关掉了。</p><p>我关掉以前，我把她那句&quot;那个酒店有单人房&quot;从里面复制出来。</p><p>我把它放进那个没有名字的文件夹。</p><p>那天那个文件夹从 3.4 个 G，变成 3.4 个 G 多四个字节。</p>',131)])])}const l=t(_,[["render",r]]);export{q as __pageData,l as default};
